//! The two desk-signed messages (L1 contract C3). The borsh encoding of each struct is
//! exactly the byte string the desk signs. The quote travels only as the message of
//! the `Ed25519Program` verify instruction, which `open_pending` decodes; the
//! cash-out quote is also `cash_out`'s argument, and the program requires the
//! verified bytes to equal its borsh encoding. The layout, with offsets and a worked
//! signature, is in `fixtures/schedina/quote_vector.json` (generated by
//! `tests/quote_vector.rs`, which fails if the file drifts).

use anchor_lang::prelude::*;

/// One leg as quoted by the desk (85 bytes borsh).
#[derive(
    AnchorSerialize, AnchorDeserialize, InitSpace, Clone, Copy, Debug, Default, PartialEq, Eq,
)]
pub struct QuoteLeg {
    /// sha256 of the Pascal symbol string, e.g. `NBA_26OCT28_PHIIND_ML.PHI`.
    pub symbol_hash: [u8; 32],
    /// sha256 of `display_attributes.game_page.game_id`, e.g. `nba-phi-ind-2026-10-28`.
    pub game_id_hash: [u8; 32],
    /// `expected_event_start_time_ms / 1000`.
    pub start_ts: i64,
    /// 0 long, 1 short.
    pub side: u8,
    /// Ask-side quote price `p_i` for the user's side, micro-units in `(0, 1e6]`.
    pub price_u: u64,
    /// Per-leg margin, 30_000 (no overlap) or 50_000 (overlap).
    pub m1_ppm: u32,
}

/// Desk quote. Signed bytes = borsh of this struct:
/// `tag[17] ‖ program_id[32] ‖ u32 LE leg count ‖ legs (85 B each) ‖ stake_u u64 ‖
/// odds_offered_u u64 ‖ quote_expires_at i64` = `77 + 85 n` bytes.
/// Not bound to a user (the Tray quotes before a wallet connects).
#[derive(AnchorSerialize, AnchorDeserialize, Clone, Debug, PartialEq, Eq)]
pub struct QuoteMsg {
    /// `b"schedina/quote/v1"`.
    pub tag: [u8; 17],
    /// This program's id (no replay on another deployment).
    pub program_id: Pubkey,
    /// `n = legs.len()`, in ticket order.
    pub legs: Vec<QuoteLeg>,
    pub stake_u: u64,
    pub odds_offered_u: u64,
    /// Desk TTL; `open_pending` needs `now <= quote_expires_at`.
    pub quote_expires_at: i64,
}

/// Desk cash-out quote. Signed bytes = borsh of this struct:
/// `tag[19] ‖ program_id[32] ‖ ticket[32] ‖ c_u u64 ‖ ts i64` = 99 bytes.
#[derive(AnchorSerialize, AnchorDeserialize, Clone, Debug, PartialEq, Eq)]
pub struct CashOutMsg {
    /// `b"schedina/cashout/v1"`.
    pub tag: [u8; 19],
    pub program_id: Pubkey,
    /// The `Ticket` PDA.
    pub ticket: Pubkey,
    /// Amount paid to the user, micro-USDC, `<= Ticket.payout_u`.
    pub c_u: u64,
    /// Desk Unix time of the quote; valid while `|now - ts| <= 30`.
    pub ts: i64,
}
